// EDIT THIS LIST: one entry per deployment to check in on.
// deployment_ref = the deployment id, or any of its mapped refs.
const deployments = [
  { deployment_ref: 'REPLACE-WITH-DEPLOYMENT-ID', name: 'Procurement assistant', owner_email: 'owner@example.com' },
];

// Last week, Monday to Sunday (UTC).
const now = new Date();
const dow = (now.getUTCDay() + 6) % 7;
const monday = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - dow - 7));
const sunday = new Date(monday.getTime() + 6 * 86400000);
const iso = (d) => d.toISOString().slice(0, 10);

return deployments.map((d) => ({ json: { ...d, period_start: iso(monday), period_end: iso(sunday) } }));

// Turn each form response into human-time records. Unanswered requests (timed out) are skipped.
// TODO: confirm the form answers arrive under $json.data in your n8n version (Send and Wait output).
const asked = $('Deployments and last week').all();
const out = [];
$input.all().forEach((item, i) => {
  const answers = item.json.data || item.json;
  const d = asked[i]?.json;
  if (!d || !answers) return;
  for (const activity of ['review', 'fix', 'escalation', 'maintenance']) {
    const minutes = Number(answers[activity]);
    if (!Number.isFinite(minutes) || minutes <= 0) continue;
    out.push({
      deployment_ref: d.deployment_ref,
      period_start: d.period_start,
      period_end: d.period_end,
      activity,
      minutes,
      logged_by: d.owner_email,
      // Stable id: re-running the check-in for the same week updates, never duplicates.
      external_id: `n8n-checkin:${d.deployment_ref}:${d.period_start}:${activity}`,
    });
  }
});
return out.length ? [{ json: { records: out } }] : [];
